function init$FlowMulti$GridQuery$&Identity;(g) {
	var f = g._$parentForm, c = String.fromCharCode(253), a = f._$queryFilterString.split(c);
	g._alterTitle = [null, [['%d1', formatDateView(a[0]), true], ['%d2', formatDateView(a[1]), true]]];
}
function load$FlowMulti$GridQuery$&Identity;(g) {
	g.add_commandEvent(on$&Identity;$ExecuteCommand);
	g.add_onResponseComplete(on$&Identity;$ResponseComplete);
	var fieldKey = 'xkey', fieldShow = 'so_the_ts,ten_ts', fieldOver = 'chon';
	g._$t = g._getColumnOrder('chon');
	g._$k = [];
	g._$f = fieldKey.split(',');
	g._$i = getIndexByName(g, fieldKey);
	g._$s = getIndexByName(g, fieldOver);
	g._$fShow = fieldShow.split(',');
	g._$fShowIndex = getIndexByName(g, fieldShow);
	&AutoGenerate.DeclareStruct;
}
function dispose$FlowMulti$GridQuery$&Identity;(g) {
	try {g.remove_onResponseComplete(on$&Identity;$ResponseComplete);} catch (ex) {}
	try {g.remove_commandEvent(on$&Identity;$ExecuteCommand);} catch (ex) {}
	g._$t = g._$k = g._$f = g._$i = g._$s = g._$fShow = g._$fShowIndex = null;
}
function scatter$FlowMulti$GridQuery$&Identity;(g) {
	scatter$FlowMulti$GridQuery(g);
	setValueToInputData$(g);
}

function on$&Identity;$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g._$parentForm;
	switch (action) {
		case 'InformationGroup':
			switch (e.type.Value) {
				case '10':
					if (isCheck$Grid(g)) g.showForm('TSInformationDeclare');
					break;
				case '20':
					var r = g._activeRow;
					if (r == -1) break;
					var key = getKey$ByRow(g, r), d = g._$dataGL;
					var index = getIndexItem$Array$ByKey(g, d.Client, key);
					if (index == -1) {
						var indexEx = getIndexItem$Array$ByKey(g, d.Declare, key, true);
						var s1 = '', s2 = '', s3 = '', s4 = '';
						if (indexEx != -1) {
							var item = d.Declare[indexEx];
							s1 = item[d.GetIndexEx['ma_bp']];
							s2 = item[d.GetIndexEx['ten_bp']];
							s3 = item[d.GetIndexEx['tk_cp']];
							s4 = item[d.GetIndexEx['ten_tk_cp']];
						}
						g._$dataGL.Row = g._activeRow;
						g.request(g, 'InformationEdit', 'InformationEdit', [
							['ma_pl_cc', 'String', g._getItemValue(r, g._getColumnOrder('ma_pl_cc'))],
							['ma_nt', 'String', g._getItemValue(r, g._getColumnOrder('ma_nt'))],
							['tk_du', 'String', g._getItemValue(r, g._getColumnOrder('tk_vt'))],
							['tk_no', 'String', g._getItemValue(r, g._getColumnOrder('tk_vt'))],
							['ngay_ct', 'DateTime', g._getItemValue(r, g._getColumnOrder('ngay_ct'))],
							['ma_bp', 'String', g._getItemValue(r, g._getColumnOrder('ma_bp'))],
							['ma_bp_ex', 'String', s1],
							['ten_bp_ex', 'String', s2],
							['tk_cp_ex', 'String', s3],
							['ten_tk_cp_ex', 'String', s4]
						]);
						break;
					}
					g._$dataGL.IndexActive = index;
					g.showForm('TSCreateAuto');
					break;
			}
			break;
		default:
			break;
	}
}
function on$&Identity;$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'InformationEdit':
			var d = g._$dataGL, a = d.FieldGridValue;

			// Add values to the grid
			for (var i = 0; i < a.length; i++) {result[0].push(g._getItemValue(d.Row, g._getColumnOrder(a[i])));}
			var y1 = createObjectByArray$GridJson(g, result, '&Fields.Data.Client;');
			d.Client.push(y1.Data[0]);
			d.IndexActive = d.Client.length - 1;
			g.showForm('TSCreateAuto');
			break;
		default:
			break;
	}
}
function toggle$FlowMulti$GridQuery$&Identity;(o) {
	var c = o.parentNode.parentNode.parentNode.id, g = $find($func.left(c, c.length - 11)), l = g._getColumnOrder('chon');
	var f = g.get_element().parentForm;

	for (var r = 1; r <= g._rowCount; r++) {
		if (!g._getItem(r, l).disabled) {
			g._setItemValue(r, l, !g._getItemValue(r, l));
			var o = g._getItem(r, l);
			if (o.checked) {
				addTagRow$FlowMulti$(g, r);
			}
			else removeTagRow$FlowMulti$(g, r);
		}
	}

	if (g._rowCount <= 0) return;
	else {
		g._activeRow = g._rowCount;
		g._activeColumn = l;
		g._activeCell = g._getItem(g._activeRow, g._activeColumn);
	}
}

function onClick$FlowMulti$GridQuery$&Identity;Calculate(o) {
	var g = o.grid, a = o.id.split('_inputCell_'), r = a[1].split('.')[0];
	var g = o.grid, a = o.id.split('_inputCell_'), r = a[1].split('.')[0];
	if (!g) g = $find(a[0]);
	if (o.checked) {
		addTagRow$FlowMulti$(g, r);
	}
	else removeTagRow$FlowMulti$(g, r);
}
